const HEADER = 'date,description,amount,category';

export function parseCSV(text) {
  if (!text || !text.trim()) {
    return [];
  }

  // Parse the whole text in one pass so quoted fields may contain line breaks
  const rows = [];
  let row = [];
  let currentField = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          currentField += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        currentField += ch;
      }
    } else if (ch === '"' && currentField === '') {
      inQuotes = true;
    } else if (ch === ',') {
      row.push(currentField);
      currentField = '';
    } else if (ch === '\n') {
      row.push(currentField);
      rows.push(row);
      row = [];
      currentField = '';
    } else if (ch === '\r' && text[i + 1] === '\n') {
      // CRLF line ending: the \n on the next iteration ends the row
      continue;
    } else {
      currentField += ch;
    }
  }
  row.push(currentField);
  rows.push(row);

  if (rows.length === 0) {
    return [];
  }

  // Check if first row is header
  let startIndex = 0;
  const firstRow = rows[0].map((c) => c.trim().toLowerCase());
  if (
    firstRow.length >= 4 &&
    firstRow[0] === 'date' &&
    firstRow[1] === 'description' &&
    firstRow[2] === 'amount' &&
    firstRow[3] === 'category'
  ) {
    startIndex = 1;
  }

  const items = [];
  for (let r = startIndex; r < rows.length; r++) {
    const row = rows[r];
    if (row.length === 1 && row[0] === '') {
      continue;
    }
    const [date = '', description = '', amountStr = '0', category = ''] = row;
    items.push({
      date,
      description,
      amount: Number(amountStr),
      category,
    });
  }

  return items;
}

function escapeCSVField(value) {
  const str = value == null ? '' : String(value);
  if (
    str.includes(',') ||
    str.includes('"') ||
    str.includes('\n') ||
    str.includes('\r')
  ) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

export function toCSV(items) {
  const lines = [HEADER];
  for (const item of items || []) {
    const row = [
      escapeCSVField(item.date),
      escapeCSVField(item.description),
      escapeCSVField(item.amount),
      escapeCSVField(item.category),
    ];
    lines.push(row.join(','));
  }
  return lines.join('\n');
}

