}

function renderReports() {
  if (!reportBody) return;
  const month = (reportMonthInput && reportMonthInput.value) || getDefaultMonth();
  const current = summarize(transactions, monthRange(month)).byCategory;
  const previous = summarize(transactions, monthRange(shiftMonth(month, -1))).byCategory;

  // Current month's categories first, then categories only present last month
  const categories = Object.keys(current);
  for (const cat of Object.keys(previous)) {
    if (!hasOwn(current, cat)) categories.push(cat);
  }

  reportBody.innerHTML = '';
  for (const cat of categories) {
    const total = hasOwn(current, cat) ? Number(current[cat]) : 0;
    const prevTotal = hasOwn(previous, cat) ? Number(previous[cat]) : 0;

    const tr = document.createElement('tr');

    const tdCat = document.createElement('td');
    tdCat.textContent = cat;

    const tdTotal = document.createElement('td');
    tdTotal.textContent = total.toFixed(2);

    const tdChange = document.createElement('td');
    tdChange.textContent = formatChange(total - prevTotal);

    tr.appendChild(tdCat);
    tr.appendChild(tdTotal);
    tr.appendChild(tdChange);
