    const description = descriptionInput ? descriptionInput.value.trim() : '';
    const amount = amountInput ? Number(amountInput.value) : 0;
    const category = categoryInput ? categoryInput.value.trim() : '';
    const repeat = repeatSelect ? repeatSelect.value : 'none';
    const until = untilInput ? untilInput.value.trim() : '';

    if (!date || Number.isNaN(amount)) return;

    if (editIndex !== null) {
      const updated = { date, description, amount, category };
      transactions = transactions.map((item, idx) => (idx === editIndex ? updated : item));
      history.push(transactions);
      saveTransactions(transactions);
      exitEditMode();
      renderAll();
      return;
    }

