      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (cancelEditBtn) {
  cancelEditBtn.addEventListener('click', () => {
    if (editIndex !== null) exitEditMode();
  });
}

if (searchInput) {
  searchInput.addEventListener('input', () => renderTransactions());
  searchInput.addEventListener('change', () => renderTransactions());
}

if (sortAmountHeader) {
  sortAmountHeader.addEventListener('click', () => {
    sortDesc = true;
    renderTransactions();
  });
}

if (undoBtn) {
  undoBtn.addEventListener('click', () => {
    if (history.canUndo()) {
      transactions = history.undo();
      saveTransactions(transactions);
      exitEditMode();
      renderAll();
    }
  });
}

if (redoBtn) {
  redoBtn.addEventListener('click', () => {
    if (history.canRedo()) {
      transactions = history.redo();
      saveTransactions(transactions);
      exitEditMode();
      renderAll();
    }
  });
}

if (importInput) {
  importInput.addEventListener('change', async () => {
    const file = importInput.files && importInput.files[0];
    if (!file) return;

    let text = '';
    if (typeof file.text === 'function') {
      text = await file.text();
    } else {
      text = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error);
        reader.readAsText(file);
      });
    }

    const imported = parseCSV(text);
    if (imported.length > 0) {
      transactions = [...transactions, ...imported];
      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (exportBtn) {
  exportBtn.addEventListener('click', () => {
