    if (!from || !to || from === to) return;

    // Transactions are undoable; budgets are renamed in place
    if (transactions.some((item) => item.category === from)) {
      transactions = transactions.map((item) =>
        item.category === from ? { ...item, category: to } : item
      );
      history.push(transactions);
      saveTransactions(transactions);
    }

    budgets = budgets.map((b) => (b.category === from ? { ...b, category: to } : b));
    saveBudgets(budgets);
    renderAll();
  });
}

if (budgetMonthInput) {
  budgetMonthInput.addEventListener('input', () => renderBudgets());
  budgetMonthInput.addEventListener('change', () => renderBudgets());
}

if (reportMonthInput) {
  reportMonthInput.addEventListener('input', () => renderReports());
  reportMonthInput.addEventListener('change', () => renderReports());
}

// Initial render: honour the current hash (empty hash shows transactions)
updateView();

