  const thead = listTable.querySelector('thead');
  const headerTr = thead && thead.querySelector('tr');
  if (thead && headerTr) {
    while (headerTr.firstChild) {
      thead.appendChild(headerTr.firstChild);
    }
    headerTr.remove();
  }
}

