      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (cancelEditBtn) {
  cancelEditBtn.addEventListener('click', () => {
    if (editIndex !== null) exitEditMode();
  });
}

if (searchInput) {
  searchInput.addEventListener('input', () => renderTransactions());
  searchInput.addEventListener('change', () => renderTransactions());
}

if (sortAmountHeader) {
  sortAmountHeader.addEventListener('click', () => {
    sortDesc = true;
    renderTransactions();
  });
}

if (undoBtn) {
  undoBtn.addEventListener('click', () => {
    if (history.canUndo()) {
      transactions = history.undo();
      saveTransactions(transactions);
      exitEditMode();
      renderAll();
    }
  });
}

if (redoBtn) {
  redoBtn.addEventListener('click', () => {
    if (history.canRedo()) {
      transactions = history.redo();
      saveTransactions(transactions);
      exitEditMode();
      renderAll();
    }
  });
}

if (importInput) {
  importInput.addEventListener('change', async () => {
    const file = importInput.files && importInput.files[0];
    if (!file) return;

    let text = '';
    if (typeof file.text === 'function') {
      text = await file.text();
    } else {
      text = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error);
        reader.readAsText(file);
      });
    }

    const imported = parseCSV(text);
    if (imported.length > 0) {
      transactions = [...transactions, ...imported];
      history.push(transactions);
      saveTransactions(transactions);
      renderAll();
    }
  });
}

if (exportBtn) {
  exportBtn.addEventListener('click', () => {
    const csvContent = toCSV(transactions);
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'transactions.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
}

if (budgetAddBtn) {
  budgetAddBtn.addEventListener('click', () => {
    const category = budgetCategoryInput ? budgetCategoryInput.value.trim() : '';
    const limit = budgetLimitInput ? Number(budgetLimitInput.value) : 0;
    if (!category || !(limit > 0)) return;

    budgets = [...budgets, { category, limit }];
    saveBudgets(budgets);
    renderBudgets();
  });
}

if (renameBtn) {
  renameBtn.addEventListener('click', () => {
    const from = renameFromInput ? renameFromInput.value.trim() : '';
    const to = renameToInput ? renameToInput.value.trim() : '';
    if (!from || !to || from === to) return;

    // Transactions are undoable; budgets are renamed in place
    if (transactions.some((item) => item.category === from)) {
      transactions = transactions.map((item) =>
        item.category === from ? { ...item, category: to } : item
      );
      history.push(transactions);
      saveTransactions(transactions);
    }

    budgets = budgets.map((b) => (b.category === from ? { ...b, category: to } : b));
    saveBudgets(budgets);
    renderAll();
  });
}

if (budgetMonthInput) {
  budgetMonthInput.addEventListener('input', () => renderBudgets());
  budgetMonthInput.addEventListener('change', () => renderBudgets());
}

if (reportMonthInput) {
  reportMonthInput.addEventListener('input', () => renderReports());
  reportMonthInput.addEventListener('change', () => renderReports());
}

// Initial render: honour the current hash (empty hash shows transactions)
